package com.lexorion.gateway;
import static org.assertj.core.api.Assertions.assertThat;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;
class CorrelationIdFilterTest{@Test void generatesAndForwardsCorrelationId()throws Exception{var filter=new CorrelationIdFilter();var request=new MockHttpServletRequest("GET","/api/platform/users");var response=new MockHttpServletResponse();var forwarded=new AtomicReference<String>();filter.doFilter(request,response,(req,res)->forwarded.set(((jakarta.servlet.http.HttpServletRequest)req).getHeader(CorrelationIdFilter.HEADER)));assertThat(response.getHeader(CorrelationIdFilter.HEADER)).isNotBlank().isEqualTo(forwarded.get());}@Test void preservesSafeCallerCorrelationId()throws Exception{var filter=new CorrelationIdFilter();var request=new MockHttpServletRequest("GET","/");request.addHeader(CorrelationIdFilter.HEADER,"request-123");var response=new MockHttpServletResponse();filter.doFilter(request,response,(req,res)->{});assertThat(response.getHeader(CorrelationIdFilter.HEADER)).isEqualTo("request-123");}}
